exports.allocate = allocate;
exports.bendFor = bendFor;
exports.pitchOf = pitchOf;
exports.impliedRange = impliedRange;
exports.zoneConfig = zoneConfig;
exports.noteOn = noteOn;
exports.noteOff = noteOff;
