      const length = vlq();
      check(pos + length <= end, `track ${track + 1}: a meta event runs past the track`);
      events.push({ tick, track, order: order++, meta, data: Array.from(bytes.slice(pos, pos + length)) });
      pos += length;
      status = 0;
      if (meta === 0x2f) break;
